}

enum TrackingStage: String, Codable, CaseIterable, Hashable, Sendable, Identifiable {
    case pending
    case registered
    case accepted
    case inTransit = "in_transit"
    case outForDelivery = "out_for_delivery"
    case delivered
    case customs
    case failedAttempt = "failed_attempt"
    case readyForPickup = "ready_for_pickup"
    case returned
    case exception

    var id: String { rawValue }
}

enum SyncStatus: String, Codable, CaseIterable, Hashable, Sendable, Identifiable {
    case pending
    case syncing
    case ok
    case waiting
    case error
    case unsupported

    var id: String { rawValue }
}

enum RecipientAction: String, Codable, CaseIterable, Hashable, Sendable, Identifiable {
    case taxID = "tax_id"
    case duties
    case documents

    var id: String { rawValue }
}

